func (q *Queries) ListUserActiveTayfas(ctx context.Context, arg ListUserActiveTayfasParams) ([]ListUserActiveTayfasRow, error) {
	rows, err := q.db.Query(ctx, listUserActiveTayfas, arg.UserID, arg.AfterID, arg.PageSize)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListUserActiveTayfasRow{}
	for rows.Next() {
		var i ListUserActiveTayfasRow
		if err := rows.Scan(
			&i.ID,
			&i.Name,
			&i.Description,
			&i.Status,
			&i.JoinPolicy,
			&i.SuspendedAt,
			&i.DeletionScheduledFor,
			&i.Role,
			&i.MutedUntil,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

